BEGIN READ ONLY;
SELECT jsonb_build_object(
'schemas',(select jsonb_agg(nspname order by nspname) from pg_namespace where nspname in ('public','place_private','proposal_private','travel_book_private')),
'columns',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname in ('public','place_private','proposal_private','travel_book_private') and c.relkind in ('r','p') and a.attnum>0 and not a.attisdropped),
'tables',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'kind',c.relkind) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','place_private','proposal_private','travel_book_private') and c.relkind in ('r','p')),
'constraints',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',co.conname,'type',co.contype,'definition',pg_get_constraintdef(co.oid,true)) order by co.contype,n.nspname,c.relname,co.conname) from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','place_private','proposal_private','travel_book_private')),
'indexes',(select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',indexname,'definition',indexdef) order by schemaname,tablename,indexname) from pg_indexes where schemaname in ('public','place_private','proposal_private','travel_book_private')),
'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'acl',p.proacl::text,'owner',pg_get_userbyid(p.proowner),'extension',exists(select 1 from pg_depend dep where dep.objid=p.oid and dep.deptype='e')) order by n.nspname,p.proname,p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','place_private','proposal_private','travel_book_private') and p.prokind in ('f','p')),
'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','place_private','proposal_private','travel_book_private') and not t.tgisinternal),
'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname in ('public','place_private','proposal_private','travel_book_private') or (schemaname='storage' and tablename='objects')),
'grants',(select jsonb_agg(to_jsonb(g) order by table_schema,table_name,grantee,privilege_type) from information_schema.role_table_grants g where table_schema in ('public','place_private','proposal_private','travel_book_private')),
'enums',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'label',e.enumlabel,'sort',e.enumsortorder) order by n.nspname,t.typname,e.enumsortorder) from pg_type t join pg_namespace n on n.oid=t.typnamespace join pg_enum e on e.enumtypid=t.oid where n.nspname in ('public','place_private','proposal_private','travel_book_private')),
'extensions',(select jsonb_agg(jsonb_build_object('name',e.extname,'schema',n.nspname,'version',e.extversion) order by e.extname) from pg_extension e join pg_namespace n on n.oid=e.extnamespace),
'publication',(select jsonb_agg(jsonb_build_object('publication',pubname,'schema',schemaname,'table',tablename)) from pg_publication_tables where pubname='supabase_realtime')
) as snapshot;
COMMIT;
